-- Disposable cluster only. Every fixture and mutation is rolled back.
begin;
create function pg_temp.assert_true(condition boolean,label text) returns void language plpgsql as $$
begin if condition is not true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(statement text,code text,label text) returns void language plpgsql as $$
declare failed boolean:=false;begin begin execute statement;exception when others then if sqlstate<>code then raise exception 'FAIL: % expected % got %',label,code,sqlstate;end if;failed:=true;end;if not failed then raise exception 'FAIL: % unexpectedly succeeded',label;end if;raise notice 'PASS: %',label;end;$$;
insert into auth.users(id,email_confirmed_at) values('00000000-0000-4000-a000-000000000001',now()),('00000000-0000-4000-a000-000000000002',now());
update public.profiles set username=case id when '00000000-0000-4000-a000-000000000001' then 'alice' else 'bob' end,display_name='Test maker';
insert into auth.identities(id,user_id,provider,provider_id) values('80000000-0000-4000-a000-000000000001','00000000-0000-4000-a000-000000000001','github','7');
insert into public.projects(id,maker_id,name,tagline,description,category_id,status,published_at,publish_request_key,github_url) values
('10000000-0000-4000-a000-000000000001','00000000-0000-4000-a000-000000000001','Ownership fixture','A shipped verification fixture',repeat('Description. ',20),(select id from public.categories where slug='developer-tools'),'published',now(),gen_random_uuid(),'https://github.com/alice/work');
set local role anon;
select pg_temp.assert_true(public.get_public_repository_verification('10000000-0000-4000-a000-000000000001') is null,'unchecked project has no public claim');
select pg_temp.expect_error($q$select public.begin_repository_verification('10000000-0000-4000-a000-000000000001')$q$,'42501','anonymous checks denied');
select pg_temp.expect_error($q$select * from private.repository_verifications$q$,'42501','private evidence is not public');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000002',true);
set local role authenticated;
select pg_temp.expect_error($q$select public.begin_repository_verification('10000000-0000-4000-a000-000000000001')$q$,'42501','other maker cannot begin check');
select pg_temp.expect_error($q$select public.complete_repository_verification('10000000-0000-4000-a000-000000000001',gen_random_uuid(),42,7,'https://github.com/alice/work')$q$,'42501','authenticated clients cannot forge server evidence');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-a000-000000000001',true);
set local role authenticated;
select public.begin_repository_verification('10000000-0000-4000-a000-000000000001');
reset role;
select pg_temp.assert_true(not public.complete_repository_verification('10000000-0000-4000-a000-000000000001',gen_random_uuid(),42,7,'https://github.com/alice/work'),'wrong attempt cannot commit');
select pg_temp.assert_true(not public.complete_repository_verification('10000000-0000-4000-a000-000000000001',(select attempt_id from private.repository_verifications),42,8,'https://github.com/alice/work'),'wrong owner cannot commit');
select pg_temp.assert_true(not public.complete_repository_verification('10000000-0000-4000-a000-000000000001',(select attempt_id from private.repository_verifications),42,7,'https://github.com/alice/other'),'wrong URL cannot commit');
select set_config('ark.verification_attempt',(select attempt_id::text from private.repository_verifications),true);
set local role service_role;
select pg_temp.assert_true(public.complete_repository_verification('10000000-0000-4000-a000-000000000001',current_setting('ark.verification_attempt')::uuid,42,7,'https://github.com/alice/work'),'trusted matching response commits');
reset role;
set local role anon;
select pg_temp.assert_true(public.get_public_repository_verification('10000000-0000-4000-a000-000000000001')->>'state'='verified','public verified summary is available');
select pg_temp.assert_true(not (public.get_public_repository_verification('10000000-0000-4000-a000-000000000001') ? 'github_user_id'),'summary excludes private evidence');
reset role;
select pg_temp.assert_true(not public.complete_repository_verification('10000000-0000-4000-a000-000000000001',(select attempt_id from private.repository_verifications),42,7,'https://github.com/alice/work'),'completed attempt cannot replay');
update private.repository_verifications set expires_at=now()-interval '1 second',checked_at=now()-interval '91 days';
select pg_temp.assert_true(public.get_public_repository_verification('10000000-0000-4000-a000-000000000001')->>'state'='expired','expired claim becomes expired summary');
set local role authenticated;
select public.begin_repository_verification('10000000-0000-4000-a000-000000000001');
reset role;
select pg_temp.assert_true(public.get_public_repository_verification('10000000-0000-4000-a000-000000000001') is null,'new check clears old claim even if provider fails');
update public.projects set version=version+1;
select pg_temp.assert_true(not public.complete_repository_verification('10000000-0000-4000-a000-000000000001',(select attempt_id from private.repository_verifications),42,7,'https://github.com/alice/work'),'edit racing with check prevents stale commit');
set local role authenticated;
select public.begin_repository_verification('10000000-0000-4000-a000-000000000001');
reset role;
select public.complete_repository_verification('10000000-0000-4000-a000-000000000001',(select attempt_id from private.repository_verifications),42,7,'https://github.com/alice/work');
update public.projects set github_url='https://github.com/alice/other';
update public.projects set github_url='https://github.com/alice/work';
select pg_temp.assert_true(public.get_public_repository_verification('10000000-0000-4000-a000-000000000001') is null,'changing link back does not resurrect verification');
set local role authenticated;
select public.begin_repository_verification('10000000-0000-4000-a000-000000000001');
reset role;
select public.complete_repository_verification('10000000-0000-4000-a000-000000000001',(select attempt_id from private.repository_verifications),42,7,'https://github.com/alice/work');
update private.account_controls set status='suspended' where user_id='00000000-0000-4000-a000-000000000001';
select pg_temp.assert_true(public.get_public_repository_verification('10000000-0000-4000-a000-000000000001') is null,'suspension removes public verification');
set local role authenticated;
select pg_temp.expect_error($q$select public.begin_repository_verification('10000000-0000-4000-a000-000000000001')$q$,'42501','suspended maker cannot check');
reset role;
update private.account_controls set status='active';
update public.projects set status='hidden';
update public.projects set status='published';
select pg_temp.assert_true(public.get_public_repository_verification('10000000-0000-4000-a000-000000000001') is null,'hide and restore require a new check');
set local role authenticated;
select public.begin_repository_verification('10000000-0000-4000-a000-000000000001');
reset role;
delete from auth.identities where provider='github';
select pg_temp.assert_true((select count(*)=0 from private.repository_verifications),'disconnect deletes linked verification evidence');
set local role authenticated;
select pg_temp.expect_error($q$select public.begin_repository_verification('10000000-0000-4000-a000-000000000001')$q$,'22023','missing GitHub identity cannot check');
reset role;
insert into auth.identities(user_id,provider,provider_id) values('00000000-0000-4000-a000-000000000001','github','7');
select pg_temp.assert_true(public.get_public_repository_verification('10000000-0000-4000-a000-000000000001') is null,'reconnecting same account does not resurrect claim');
set local role authenticated;
select public.begin_repository_verification('10000000-0000-4000-a000-000000000001');
reset role;
select set_config('ark.old_attempt',(select attempt_id::text from private.repository_verifications),true);
set local role authenticated;
select public.begin_repository_verification('10000000-0000-4000-a000-000000000001');
reset role;
select pg_temp.assert_true(not public.complete_repository_verification('10000000-0000-4000-a000-000000000001',current_setting('ark.old_attempt')::uuid,42,7,'https://github.com/alice/work'),'overlapping checks cannot commit an older response');
update private.repository_verifications set attempt_until=now()-interval '1 second';
select pg_temp.assert_true(not public.complete_repository_verification('10000000-0000-4000-a000-000000000001',(select attempt_id from private.repository_verifications),42,7,'https://github.com/alice/work'),'expired attempts cannot commit');
update private.rate_limits set count=10 where action='repository_verification';
set local role authenticated;
select pg_temp.expect_error($q$select public.begin_repository_verification('10000000-0000-4000-a000-000000000001')$q$,'P0001','hourly limit enforced');
reset role;
rollback;
